input.sparql:
SELECT ?point ?tsid WHERE {
  ?point a brick:ElectricPowerMeter .
  ?point ref:hasExternalReference ?ext .
  ?ext ref:hasTimeseriesId ?tsid .
} LIMIT 50

SELECT ?point ?class ?tsid WHERE {
  ?point a ?class .
  OPTIONAL { ?point ref:hasExternalReference ?ext . ?ext ref:hasTimeseriesId ?tsid . }
  FILTER(str(?class) LIKE "brick:%")
} LIMIT 200

SELECT ?point ?class ?tsid WHERE {
  ?point a ?class .
  OPTIONAL { ?point ref:hasExternalReference ?ext . ?ext ref:hasTimeseriesId ?tsid . }
} LIMIT 200

SELECT ?point ?class ?tsid WHERE {
  ?point a ?class .
  ?point ref:hasExternalReference ?ext .
  ?ext ref:hasTimeseriesId ?tsid .
  FILTER(str(?class) LIKE "https://brickschema.org/schema/Brick#Electric%")
} LIMIT 200

SELECT ?point ?class ?tsid WHERE {
  ?point a ?class .
  ?point ref:hasExternalReference ?ext .
  ?ext ref:hasTimeseriesId ?tsid .
  FILTER(CONTAINS(str(?class), "Electric"))
} LIMIT 200
